import sys
from collections import defaultdict

def main():
    import sys
    input = sys.stdin.read().split()
    n = int(input[0])
    p = [int(x) for x in input[1:]]

    graph = defaultdict(list)
    for i in range(n):
        if p[i] != -1:
            graph[p[i]].append(i + 1)

    def dfs(node):
        if node in memo:
            return memo[node]
        depth = 0
        for neighbor in graph[node]:
            depth = max(depth, dfs(neighbor))
        memo[node] = depth + 1
        return depth + 1

    memo = {}
    max_depth = 0
    for i in range(1, n + 1):
        if p[i - 1] == -1:
            max_depth = max(max_depth, dfs(i))

    print(max_depth)

main()
